{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tetrabenazine, the closest structural analogue (transfer 0.907), showed mean systemic availability of only 0.049 ± 0.032 after oral administration in patients, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Meptazinol, a structurally related N-methyl analgesic with phenolic character, had absolute oral bioavailability of only 4.5–8.7% in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine, another N-methyl phenolic opioid analogue, had a mean oral bioavailability of 18% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Estradiol, a phenolic compound subject to extensive first-pass conjugation, had absolute oral bioavailability of approximately 1–5%, supporting low F for phenolic/methoxy-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Curcumin, a polyphenolic compound, had peroral bioavailability of barely 1% in humans due to poor solubility and rapid conjugation, reinforcing the low-F pattern.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well below 20% (tetrabenazine ~5%, meptazinol ~9%, pentazocine ~18%, estradiol ~5%, curcumin ~1%). The query shares key structural features—benzo-fused N-methyl amine, phenol/methoxy substituents, and a ketone—associated with extensive first-pass metabolism, so F < 20% is strongly supported.",
  "evidence_gaps": [
    "No direct bioavailability measurement exists for the query molecule itself; prediction relies on close structural analogues.",
    "The query's specific phenolic hydroxy/methoxy pattern may alter conjugation rates relative to tetrabenazine, but the consistent low-F evidence across multiple analogues makes a high-F outcome unlikely."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

